-- == PG-ONLY:
-- legacy junction slugs outside the gazetteer become 'unresolved'
-- entities — documented, queryable, never silently dropped
SELECT 'legacy:' || s.entity_slug, s.entity_slug, 'other', 'unresolved',
       jsonb_build_object('unresolved', true, 'legacySlug', s.entity_slug)
FROM (SELECT DISTINCT entity_slug FROM event_entities) s
LEFT JOIN entities en ON en.canonical_key = 'legacy:' || s.entity_slug
     OR en.metadata->>'gazetteerSlug' = s.entity_slug
WHERE en.id IS NULL
  AND s.entity_slug NOT IN ('vietnam','hanoi','hcmc','danang','haiphong','cantho','hue','nhatrang','dalat','quangninh','hatinh','nghean','thanhhoa','laocai','langson','caobang','dienbien','sonla','gialai','daklak','angiang','kiengiang','camau','binhduong','dongnai','bariavungtau','bacninh','phuquoc','quangtri','khanhhoa','lamdong','mientrung','mienbac','miennam','taynguyen','dbscl','halong','china','japan','southkorea','northkorea','taiwan','hongkong','thailand','myanmar','laos','cambodia','malaysia','singapore','indonesia','philippines','india','pakistan','bangladesh','australia','newzealand','israel','palestine','iran','iraq','syria','lebanon','yemen','saudi','uae','qatar','turkey','russia','ukraine','uk','france','germany','italy','spain','poland','netherlands','belgium','switzerland','sweden','norway','denmark','finland','austria','greece','portugal','ireland','hungary','czech','romania','eu','us','canada','mexico','brazil','argentina','chile','peru','colombia','venezuela','cuba','panama','haiti','egypt','southafrica','nigeria','kenya','sudan','ethiopia','morocco','libya','congo','southsudan','nato','un','asean','aseancup','asiad','unga','brics','g20','middleeast','baltic','southchinasea','redsea','federal_reserve','nhnn','ecb','boj','opec','imf','worldbank','wto','who','trump','putin','zelensky','xijinping','hunsen','kimsangsik','kimjongun','netanyahu','modi','milei','lam','biden','macron','starmer','vonderleyen','pm','openai','chatgpt','anthropic','claude','spacex','starlink','falcon','tesla','meta','facebook','google','alphabet','deepmind','apple','microsoft','nvidia','bytedance','tiktok','vinfast','greensm','musk','zuckerberg','samaltman','amodei','jensenhuang','timcook','phamnhatvuong','viettel','samsung','intel','boeing','airbus','pipeline','oil','drone','ai','semiconductor','trade_surplus','song_hong','nine_eleven')
ON CONFLICT (canonical_key) DO NOTHING;

UPDATE event_entities ee
SET entity_id = en.id
FROM entities en
WHERE ee.entity_id IS NULL
  AND en.canonical_key = 'legacy:' || ee.entity_slug;

COMMIT;
